"""Simple local-review frontend over the existing full-city model."""
from pathlib import Path
import re,json
ROOT=Path(__file__).resolve().parents[1];DEST=ROOT/'netlify_site/src'
def publish(raw):
 (DEST/'research.html').write_text(raw)
 match=re.search(r'const DATA=(.*?);const map=',raw,re.S);payload=json.loads(match.group(1));payload['county']=None;payload['county_blocks']=''
 html=raw[:match.start(1)]+json.dumps(payload)+raw[match.end(1):]
 html=html.replace('<body>','<body data-public="true">').replace('<title>EmPath · Choose your walking needs</title>','<title>EmPath · Find your place. Plan your walk.</title>')
 html=html.replace('</head>','<link rel="stylesheet" href="public.css"><script src="scales.js"></script><script>window.empathPublic=true;window.empathScoreMode=new URLSearchParams(location.search).get("view")||"shade";const qBudget=Number(new URLSearchParams(location.search).get("budget"));window.empathBudget=null;window.empathMode="area";window.empathRequestedMode=new URLSearchParams(location.search).get("mode");window.empathRequestedExample=new URLSearchParams(location.search).get("example")==="1";</script></head>')
 a=html.index('<aside>');z=html.index('<div id="categories"',a)
 header='''<aside><nav class="app-nav"><a class="brand" href="index.html">EmPath</a><a href="master-map.html">Master map ↗</a></nav><h1>Life within reach.</h1><span class="model-tag">Shade-priority access</span><div class="mode-switch" role="tablist" aria-label="Explore mode"><button id="mode-area" role="tab" aria-selected="true">Find an area</button><button id="mode-route" role="tab" aria-selected="false">Plan a walk</button></div><div id="area-controls"><h2>What needs to be nearby?</h2><div class="buttons"><button id="all" class="primary">Select all</button><button id="clear">Clear all</button></div><label for="scope" hidden>Study area</label><select id="scope" hidden><option value="pilot">City of Plano</option><option value="county">County preview</option></select><div id="county-notice" hidden></div>'''
 html=html[:a]+header+html[z:]
 marker='<div id="categories" class="categories"></div>'
 html=html.replace(marker,marker+'''<form id="address-form"><label for="address-input">Have an address in mind?</label><div class="address-row"><input id="address-input" type="search" autocomplete="street-address" placeholder="Street address in Plano" maxlength="200"><button type="submit">Find</button></div></form><p id="address-status" class="subtle" aria-live="polite"></p>''')
 html=html.replace("let selected=['hindu_temple','supermarket','pharmacy']","let selected=['bank','supermarket','pharmacy']").replace("preset(['hindu_temple','supermarket','pharmacy'])","preset(['bank','supermarket','pharmacy'])")
 html=html.replace("let selected=['bank','supermarket','pharmacy']","let selected=[]")
 html=html.replace("el('essential').onclick=()=>preset(['bank','supermarket','pharmacy']);","")
 html=html.replace("hindu_temple:'Hindu temples (candidate catalog)'","hindu_temple:'Hindu temples'").replace("supermarket:'Grocery stores / supermarkets'","supermarket:'Grocery stores'")
 start=html.index('function computeScores(');end=html.index('\n(async()=>',start)
 html=html[:start]+'''function computeScores(features,lookup,selected){const rows={},eligible=[];for(const f of features){const p=f.properties,id=p.GEOID20,choices=selected.map(c=>lookup[id]?.[c]),valid=selected.length>0&&choices.every(r=>r&&Number.isFinite(r.min_friction_equivalent_minutes)&&Number.isFinite(r.baseline_time_minutes)),shade=valid?choices.reduce((s,r)=>s+r.min_friction_equivalent_minutes,0)/selected.length:null,time=valid?choices.reduce((s,r)=>s+r.baseline_time_minutes,0)/selected.length:null,mean=window.empathScoreMode==='time'?time:shade;const withinBudget=valid&&Number(p.HU100)>0&&p.access_snap_gap_m<=100;rows[id]={mean,shadeMean:shade,timeMean:time,sum:mean==null?null:mean*selected.length,reached:choices.filter(r=>r&&Number.isFinite(r.min_friction_equivalent_minutes)).length,score:null,withinBudget,coverage:valid&&choices.every(r=>r.min_friction_equivalent_minutes<Number(p.boundary_exit_lower_bound_min))};if(withinBudget)eligible.push(id)}function ranks(key){const order=eligible.slice().sort((a,b)=>rows[a][key]-rows[b][key]),r={};for(let a=0;a<order.length;){let b=a+1;while(b<order.length&&rows[order[b]][key]===rows[order[a]][key])b++;const v=order.length>1?100*((a+b-1)/2)/(order.length-1):0;for(let j=a;j<b;j++)r[order[j]]=v;a=b}return r}const sr=ranks('shadeMean'),tr=ranks('timeMean'),values=eligible.map(id=>rows[id].mean).sort((a,b)=>a-b),lo=values.length?quantile(values,.02):null,hi=values.length?quantile(values,.98):null;let changeLimit=1;for(const id of eligible){rows[id].rankDelta=sr[id]-tr[id];changeLimit=Math.max(changeLimit,Math.abs(rows[id].rankDelta))}for(const id of eligible){const r=rows[id];r.score=window.empathScoreMode==='difference'?50+50*r.rankDelta/changeLimit:hi>lo?100*Math.max(0,Math.min(1,(r.mean-lo)/(hi-lo))):0}return{rows,lo,hi,complete:eligible.length,changeLimit}}''' + html[end:]
 html=html.replace("const color=v=>v==null?'#adb5bd':palette[Math.min(4,Math.floor(Math.max(0,Math.min(99.999,v))/20))];","const color=v=>window.empathScoreMode==='difference'?window.EmPathColors.change(v):window.EmPathColors.access(v);")
 html=html.replace('window.empathContext={map,blocks,lookup,pois,layer,labels,','window.empathContext={publicMode:true,map,blocks,lookup,pois,layer,labels,')
 a=html.index("el('summary').textContent=selected.length?");z=html.index(';const params=new URLSearchParams()',a)
 html=html[:a]+'''el('summary').textContent=selected.length?`${scores.complete.toLocaleString()} residential areas compared for ${selected.length} types of places${window.empathBudget==null?'':` · ${window.empathBudget}-minute effort limit`}.`:'Choose the types of places that matter to your family.';el('legend').innerHTML='<b>Walking friction</b><div class="ramp"></div>Blue: lower → red: higher<br><small>Continuous colors compare this selection. Gray: non-residential. Amber: residential data unavailable.</small>' '''+html[z:]
 html=html.replace(';const params=new URLSearchParams()',';if(window.empathScoreMode===\'time\')el(\'legend\').innerHTML=\'<b>Walking time only</b><div class="ramp"></div>Blue: shorter → red: longer<br><small>Same graph and places; no environmental penalties.</small>\';if(window.empathScoreMode===\'difference\')el(\'legend\').innerHTML=\'<b>Ranking change</b><div class="ramp" style="background:linear-gradient(90deg,#2166ac,#f7f7f7,#b2182b)"></div>Blue: improves with friction<br>Red: worsens<br><small>Change in cost percentile.</small>\';const params=new URLSearchParams()')
 html=html.replace("if(query.get('scope')==='county')el('scope').value='county';",'')
 html=html.replace("fillColor:color(scores.rows[f.properties.GEOID20].score)","fillColor:Number(f.properties.HU100)>0?(scores.rows[f.properties.GEOID20].score==null?(selected.length?'#fff0cb':'#edf1eb'):color(scores.rows[f.properties.GEOID20].score)):'#d8dcda'")
 html=html.replace("function preset(cats)","window.empathRefresh=update;\nfunction preset(cats)")
 html=html.replace("params.set('categories',selected.join(','));","params.set('categories',selected.join(','));params.set('view',window.empathScoreMode);if(window.empathMode==='route'||window.empathRequestedMode==='route')params.set('mode','route');")
 html=html.replace("if(!selected.includes(p.category))continue;","if(window.empathPublic||!selected.includes(p.category))continue;")
 html=html.replace('Copy this selection’s link','Share this view').replace('Download block scores','Download area scores').replace('<button id="download">','<button id="download" hidden>')
 a=html.index('<p><a href="index.html">All project maps</a>');z=html.index('</aside>',a)
 html=html[:a]+'''</div><section id="wayfinder" hidden></section><section id="context-panel"></section><section id="area-context"></section><footer class="app-footer"><a href="behind.html">Behind the scores</a> · <a href="master-map.html">Master map</a> · <a href="gallery.html">Map gallery</a></footer>'''+html[z:]
 html=html.replace('<script src="routes.js">','<script src="public.js"></script><script src="route-benefits.js"></script><script src="routes.js">')
 html=html.replace('</body>','<script src="integrated.js"></script><script src="wayfinding.js"></script><script src="navigation-core.js"></script><script src="navigation.js"></script><script src="experience.js"></script><script src="app-polish.js"></script><script src="journey.js"></script></body>')
 (DEST/'app.html').write_text(html)
 return DEST/'app.html'
if __name__=='__main__':print(publish((DEST/'research.html').read_text()))
